        { q: 'Сколько длится демо по офферу?', a: ['10 минут', '30 минут', '1 час', '2 часа'], c: 1 },
        { q: 'Условие оффера «запуск за 7 дней»:', a: ['Только для A-сегмента', 'Если интеграция не требуется', 'Только с предоплатой', 'Только в декабре'], c: 1 }
